public List<Employee> findEmployeesEarninAboveDepartmentAverage(Connection connection) throws SQLException {
    // A classic correlated subquery example in raw JDBC
    String sql = "SELECT e.id, e.name, e.salary, e.department_id " +
                 "FROM employees e " +
                 "WHERE e.salary > (" +
                 "    SELECT AVG(inner_e.salary) " +
                 "    FROM employees inner_e " +
                 "    WHERE inner_e.department_id = e.department_id" +
                 ")";

    List<Employee> employees = new ArrayList<>();
    try (PreparedStatement stmt = connection.prepareStatement(sql);
         ResultSet rs = stmt.executeQuery()) {
        while (rs.next()) {
            employees.add(new Employee(
                rs.getLong("id"),
                rs.getString("name"),
                rs.getBigDecimal("salary"),
                rs.getLong("department_id")
            ));
        }
    }
    return employees;
}
